1	/**
2	 * discord.js implementation of the DiscordGateway port — the thin boundary.
3	 *
4	 * This is the ONLY file that imports discord.js. It extracts the Raw* shapes from
5	 * discord.js objects and hands them to the (pure, tested) normalization layer; it
6	 * contains no normalization or enqueue logic itself. Like the pg client, it is not
7	 * unit-tested — it needs a live gateway — so it is kept deliberately thin.
8	 */
9	
10	import { ChannelType, Client, Events, GatewayIntentBits } from 'discord.js';
11	import type { AnyThreadChannel, Message } from 'discord.js';
12	import type { BackfillQuery, DiscordGateway, RawMessage, RawThread } from './types.js';
13	
14	export interface GatewayConfig {
15	  readonly botToken: string;
16	}
17	
18	export function createDiscordGateway(config: GatewayConfig): DiscordGateway {
19	  return new DiscordJsGateway(config);
20	}
21	
22	class DiscordJsGateway implements DiscordGateway {
23	  private readonly client: Client;
24	  private readonly token: string;
25	  private threadHandler?: (thread: RawThread) => Promise<void>;
26	  private messageHandler?: (message: RawMessage) => Promise<void>;
27	
28	  constructor(config: GatewayConfig) {
29	    this.token = config.botToken;
30	    this.client = new Client({
31	      intents: [
32	        GatewayIntentBits.Guilds,
33	        GatewayIntentBits.GuildMessages,
34	        GatewayIntentBits.MessageContent,
35	      ],
36	    });
37	
38	    // Without a listener, a client 'error' (e.g. a bad token) is thrown as an
39	    // unhandled EventEmitter error and crashes the process. Swallow it here so the
40	    // rest of the service (health, worker) keeps running; login failures are
41	    // surfaced via the rejected start() promise instead.
42	    this.client.on(Events.Error, () => {});
43	
44	    this.client.on(Events.ThreadCreate, (thread) => {
45	      void this.dispatchThread(thread);
46	    });
47	    this.client.on(Events.MessageCreate, (message) => {
48	      void this.messageHandler?.(this.toRawMessage(message));
49	    });
50	  }
51	
52	  onThreadCreated(handler: (thread: RawThread) => Promise<void>): void {
53	    this.threadHandler = handler;
54	  }
55	
56	  onMessageCreated(handler: (message: RawMessage) => Promise<void>): void {
57	    this.messageHandler = handler;
58	  }
59	
60	  async start(): Promise<void> {
61	    await this.client.login(this.token);
62	  }
63	
64	  async stop(): Promise<void> {
65	    await this.client.destroy();
66	  }
67	
68	  async listThreads(query: BackfillQuery): Promise<readonly RawThread[]> {
69	    const raw: RawThread[] = [];
70	    for (const guild of this.client.guilds.cache.values()) {
71	      const forums = guild.channels.cache.filter((c) => c.type === ChannelType.GuildForum);
72	      for (const forum of forums.values()) {
73	        if (forum.type !== ChannelType.GuildForum) {
74	          continue;
75	        }
76	        const active = await forum.threads.fetchActive();
77	        for (const thread of active.threads.values()) {
78	          raw.push(await this.toRawThread(thread));
79	        }
80	        if (query.includeArchived) {
81	          const archived = await forum.threads.fetchArchived();
82	          for (const thread of archived.threads.values()) {
83	            raw.push(await this.toRawThread(thread));
84	          }
85	        }
86	      }
87	    }
88	    return raw;
89	  }
90	
91	  async listMessages(threadId: string): Promise<readonly RawMessage[]> {
92	    const channel = await this.client.channels.fetch(threadId);
93	    if (!channel || !channel.isThread()) {
94	      return [];
95	    }
96	    const collection = await channel.messages.fetch({ limit: 100 });
97	    // discord.js returns newest-first; reverse to oldest-first for ordered enqueue.
98	    return [...collection.values()].reverse().map((m) => this.toRawMessage(m));
99	  }
100	
101	  private async dispatchThread(thread: AnyThreadChannel): Promise<void> {
102	    if (!this.threadHandler) {
103	      return;
104	    }
105	    await this.threadHandler(await this.toRawThread(thread));
106	  }
